import { InferenceRequest, InferenceResponse } from './llm.js';
export class LlmServiceClientJSON {
    constructor(rpc) {
        this.rpc = rpc;
        this.Infer.bind(this);
    }
    Infer(request) {
        const data = InferenceRequest.toJSON(request);
        const promise = this.rpc.request('devvit.plugin.llm.v1alpha.LlmService', 'Infer', 'application/json', data);
        return promise.then((data) => InferenceResponse.fromJSON(data));
    }
}
export class LlmServiceClientProtobuf {
    constructor(rpc) {
        this.rpc = rpc;
        this.Infer.bind(this);
    }
    Infer(request) {
        const data = InferenceRequest.encode(request).finish();
        const promise = this.rpc.request('devvit.plugin.llm.v1alpha.LlmService', 'Infer', 'application/protobuf', data);
        return promise.then((data) => InferenceResponse.decode(data));
    }
}
